// Des: Message and chat actions: react, recall, pin, archive, block
// Flo: mode gate > halt+pace gate > open chat > hover message or click chat button > click registry key > verify > log
// I/O: Sess + chat + needle text (caller) > page state change; preview in dry mode; ask-first actions need force
// ===================================================================
const std = @import("std"); const sess = @import("ru-sess-ctxz.zig"); const opn = @import("ru-chat-open.zig"); const snd = @import("ru-chat-send.zig"); const snap = @import("ru-page-snap.zig"); const rd = @import("ru-chat-read.zig"); const extr = @import("ru-page-extr.zig"); const fnd = @import("ru-labl-find.zig"); const inpu = @import("ru-huma-inpu.zig"); const priv = @import("ru-safe-priv.zig");
pub const Act = enum { react, quote, recall, delme, pinm, down, arch, hide, unre, alia, bloc, stic };
fn keyOf(act: Act) []const u8 { return switch (act) { .react => "reac_butt", .quote => "quot_butt", .recall => "reca_butt", .delme => "delm_butt", .pinm => "pinm_butt", .down => "down_butt", .arch => "arch_butt", .hide => "hide_butt", .unre => "unre_butt", .alia => "alia_butt", .bloc => "bloc_butt", .stic => "stic_butt" }; }
pub fn needsForce(act: Act) bool { return act == .recall or act == .delme or act == .bloc; }
pub fn onMessage(act: Act) bool { return switch (act) { .react, .quote, .recall, .delme, .pinm, .down => true, else => false }; }
pub fn msgPoint(ses: *sess.Sess, needle: []const u8) !inpu.Pt { if (needle.len == 0) return error.BadJob; const ext = ses.reg.ext; if (ext.msg_sel.len > 0) { const sel = try std.json.Stringify.valueAlloc(ses.aren, ext.msg_sel, .{}); const nee = try std.json.Stringify.valueAlloc(ses.aren, needle, .{}); const js = try std.fmt.allocPrint(ses.aren, "(function(){{var a=Array.from(document.querySelectorAll({s})).filter(function(e){{return (e.getAttribute('aria-label')||e.textContent||'').indexOf({s})>=0}});if(!a.length)return '';var r=a[a.length-1].getBoundingClientRect();return Math.round(r.left+r.width/2)+','+Math.round(r.top+r.height/2)}})()", .{ sel, nee }); const txt = try snap.evalStr(ses.aren, ses.conn, js); if (txt.len == 0) return error.NoElem; var itr = std.mem.splitScalar(u8, txt, ','); const xs = itr.next() orelse return error.NoElem; const ys = itr.next() orelse return error.NoElem; return .{ .x = @floatFromInt(std.fmt.parseInt(i32, xs, 10) catch return error.NoElem), .y = @floatFromInt(std.fmt.parseInt(i32, ys, 10) catch return error.NoElem) }; } const lst = try ses.nodes(); const all = try fnd.allKey(ses.aren, &ses.reg, lst, "mesg_item"); var idx: usize = all.len; while (idx > 0) { idx -= 1; if (std.mem.find(u8, all[idx].name, needle) != null) return snap.boxCenter(ses.aren, ses.conn, all[idx].bid); } return error.NoElem; }
pub fn hoverMsg(ses: *sess.Sess, needle: []const u8) !void { var tries: u32 = 0; while (tries < 4) : (tries += 1) { const pnt = try msgPoint(ses, needle); ses.pos = try inpu.moveTo(ses.aren, ses.conn, ses.hum(), ses.pos, pnt); ses.readPause(); const again = try msgPoint(ses, needle); if (@abs(again.x - pnt.x) < 5 and @abs(again.y - pnt.y) < 5) return; } }
pub fn lastOwn(ses: *sess.Sess) ![]const u8 { if (ses.reg.ext.msg_sel.len > 0) { const ms = try extr.msgsDom(ses.aren, ses.conn, ses.reg.ext); var idx = ms.len; while (idx > 0) { idx -= 1; if (std.mem.eql(u8, ms[idx].dir, "me")) { const txt = ms[idx].text; if (fnd.selfPrefix(&ses.reg, txt)) |len| return txt[len..]; return txt; } } return error.NoElem; } const shot = try rd.msgsNow(ses); var idx = shot.len; while (idx > 0) { idx -= 1; if (std.mem.eql(u8, shot[idx].who, "me")) return shot[idx].body; } return error.NoElem; }
pub fn recallLast(ses: *sess.Sess, chat: []const u8) !bool { if (ses.mode == .read) return error.BadUsage; if (needsForce(.recall) and ses.mode == .live) return error.NeedForce; if (ses.mode == .dry) return doAct(ses, .recall, chat, "x", ""); try ses.pre(.read); _ = try opn.openChat(ses, chat); const txt = try lastOwn(ses); return doAct(ses, .recall, chat, txt, ""); }
pub fn doAct(ses: *sess.Sess, act: Act, chat: []const u8, needle: []const u8, extra: []const u8) !bool { if (ses.mode == .read) return error.BadUsage; if (chat.len == 0) return error.BadJob; if (onMessage(act) and needle.len == 0) return error.BadJob; if (needsForce(act) and ses.mode == .live) return error.NeedForce;
if (ses.mode == .dry) { try ses.pre(.read); const note = try std.fmt.allocPrint(ses.aren, "PREVIEW {s} {s} {s}", .{ @tagName(act), chat, priv.bodyLog(ses.aren, needle, ses.cfg.logz_body_enab) }); ses.logz("info", note); return false; }
try ses.pre(if (act == .react) .react else .read); _ = try opn.openChat(ses, chat); if (onMessage(act)) try hoverMsg(ses, needle);
const btn = try ses.findKey(keyOf(act)); try ses.clickNode(btn); ses.readPause();
switch (act) { .react => { if (extra.len == 0) return error.BadJob; const emo = try ses.find("button", extra); try ses.clickNode(emo); }, .stic => { if (extra.len == 0) return error.BadJob; const itm = try ses.findWith("stic_item", extra); try ses.clickNode(itm); }, .quote => { if (extra.len > 0) _ = try snd.sendText(ses, chat, extra); }, else => {} }
if (act == .react) try ses.sto.actAdd(ses.now(), "react"); const note = try std.fmt.allocPrint(ses.aren, "{s} done in {s}", .{ @tagName(act), chat }); ses.logz("info", note); ses.pause(); return true; }
